#!/usr/bin/env bash
#
# Build the self-contained catapult-server Docker image locally.
#
# The Dockerfile is GENERATED by .github/scripts/gen-catapult-dockerfile.sh rather than
# committed: stages 1-4 of it are upstream symbol/symbol's own compiler and dependency
# build (jenkins/catapult), so upstream's OS release, compiler version, dependency
# versions and install locations are followed instead of re-derived here. The only value
# nemtus fixes is the target architecture, in .github/catapult/compiler-amd64.yaml.
#
# Self-contained still means self-contained: the generated Dockerfile contains NO
# symbolplatform/* base image and uses no conan.symbol.dev remote. Every upstream layer's
# FROM is rewritten to the preceding stage, so the only images pulled are `ubuntu:<X>`.
#
# This wrapper runs the same generation the CI workflow runs, so a local build and a
# published build come from one definition.
#
# Usage:
#   client/catapult/scripts/build-docker-selfcontained.sh
#
# Environment overrides:
#   IMAGE                   image tag to build   (default: nemtus/catapult-server:local)
#   COMPILER_CONFIGURATION  compiler config path (default: .github/catapult/compiler-amd64.yaml)
#   KEEP_DOCKERFILE         set to keep the generated Dockerfile for inspection
#
# Example:
#   IMAGE=nemtus/catapult-server:v1 client/catapult/scripts/build-docker-selfcontained.sh
#
# Requires python3 with PyYAML (what upstream's configuration loader needs).

set -euo pipefail

# Resolve repository root from this script's location (.../client/catapult/scripts).
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/../../.." && pwd)"

IMAGE="${IMAGE:-nemtus/catapult-server:local}"
DOCKERFILE="$(mktemp -t Dockerfile.catapult.XXXXXX)"
if [[ -z "${KEEP_DOCKERFILE:-}" ]]; then
	trap 'rm -f "${DOCKERFILE}"' EXIT
fi

gen_args=()
if [[ -n "${COMPILER_CONFIGURATION:-}" ]]; then
	gen_args+=(--compiler-configuration "${COMPILER_CONFIGURATION}")
fi

# Provenance: the runtime image records the exact source revision in its OCI
# image.revision label. Derive it from the host checkout; mark a dirty working tree so an
# image built from uncommitted changes is not mistaken for a clean commit. Only the
# (cheap) runtime label consumes this, so it never busts the compile cache.
VCS_REF="$(git -C "${REPO_ROOT}" rev-parse --short HEAD 2>/dev/null || echo unknown)"
if ! git -C "${REPO_ROOT}" diff --quiet HEAD 2>/dev/null; then
	VCS_REF="${VCS_REF}-dirty"
fi

cd "${REPO_ROOT}"
bash .github/scripts/gen-catapult-dockerfile.sh --out "${DOCKERFILE}" "${gen_args[@]}"

# Same guard the workflow applies: a leaked symbolplatform/* reference would mean a stage
# is being pulled from Docker Hub instead of built here.
if grep -q 'symbolplatform' "${DOCKERFILE}"; then
	echo "ERROR: generated Dockerfile references symbolplatform/*; a stage would be pulled from Docker Hub." >&2
	grep -n 'symbolplatform' "${DOCKERFILE}" >&2
	exit 1
fi

echo "[*] repo root : ${REPO_ROOT}"
echo "[*] dockerfile: ${DOCKERFILE} (generated)"
echo "[*] image     : ${IMAGE}"
echo "[*] vcs ref   : ${VCS_REF}"

DOCKER_BUILDKIT=1 docker build \
	-f "${DOCKERFILE}" \
	-t "${IMAGE}" \
	--build-arg "VCS_REF=${VCS_REF}" \
	.
